IF DB_NAME() NOT LIKE 'Prosto_CRM_Page_Test[_]%' THROW 51999,'Disposable database required',1;
DECLARE @Saved TABLE(ID int,Row_Version binary(8));
DECLARE @a int,@b int,@catA int,@catB int,@item int,@otherItem int,@stamp uniqueidentifier=NEWID(),@version binary(8),@xml xml,@links xml,@seed numeric(38,0)=IDENT_CURRENT('dbo.CRM_Accounts');
INSERT @Saved EXEC CRM_Save_WorkGuide_Category 1,0,N'<row><Brand_ID>1</Brand_ID><Name_AR>عزل العلامة SQL</Name_AR><Name_EN>Brand isolation</Name_EN><Sort_Order>0</Sort_Order></row>';
SELECT @catA=ID FROM @Saved;DELETE @Saved;
INSERT @Saved EXEC CRM_Save_WorkGuide_Category 1,0,N'<row><Brand_ID>2</Brand_ID><Name_AR>عزل العلامة SQL</Name_AR><Name_EN>Brand isolation</Name_EN><Sort_Order>0</Sort_Order></row>';
SELECT @catB=ID FROM @Saved;DELETE @Saved;
BEGIN TRY EXEC CRM_Save_WorkGuide_Category 1,0,N'<row><Name_AR>بدون علامة</Name_AR><Name_EN>Missing brand</Name_EN><Sort_Order>0</Sort_Order></row>';THROW 51999,'Missing category brand accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @xml=CONVERT(xml,CONCAT('<row><Brand_ID>2</Brand_ID><Parent_ID>',@catA,'</Parent_ID><Name_AR>فرع مختلف</Name_AR><Name_EN>Wrong parent brand</Name_EN><Sort_Order>0</Sort_Order></row>'));
BEGIN TRY EXEC CRM_Save_WorkGuide_Category 1,0,@xml;THROW 51999,'Cross-brand parent accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
BEGIN TRY INSERT CRM_WorkGuide_Categories(Brand_ID,Parent_ID,Name_AR,Name_EN,AddedUser) VALUES(2,@catA,N'فرع مزور','Forged child',1);THROW 51999,'Database allowed cross-brand parent',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>547 THROW;END CATCH;
SET @xml=N'<row><Brand_ID>1</Brand_ID><Name_AR>دليل عزل العلامة SQL</Name_AR><Name_EN>Brand guide</Name_EN><Summary_AR>ملخص</Summary_AR><Summary_EN>Summary</Summary_EN><Sort_Order>0</Sort_Order><Is_Active>1</Is_Active><File_Url>/FileManager/CRMWorkGuide/22222222222222222222222222222222.pdf</File_Url><File_Name>test.pdf</File_Name><File_Extension>.pdf</File_Extension><File_Size>10</File_Size></row>';
SET @links=CONVERT(xml,CONCAT('<categories><id>',@catB,'</id></categories>'));
BEGIN TRY EXEC CRM_Save_WorkGuide_Item 1,0,@xml,@links;THROW 51999,'Guide accepted foreign category',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @links=CONVERT(xml,CONCAT('<categories><id>',@catA,'</id></categories>'));
INSERT @Saved EXEC CRM_Save_WorkGuide_Item 1,0,@xml,@links;SELECT @item=ID FROM @Saved;DELETE @Saved;
BEGIN TRY INSERT CRM_WorkGuide_ItemCategories(Item_ID,Category_ID,Brand_ID) VALUES(@item,@catB,1);THROW 51999,'Database allowed foreign guide classification',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>547 THROW;END CATCH;
SET @xml.modify('replace value of (/row/Brand_ID/text())[1] with "2"');
SET @links=CONVERT(xml,CONCAT('<categories><id>',@catB,'</id></categories>'));
INSERT @Saved EXEC CRM_Save_WorkGuide_Item 1,0,@xml,@links;SELECT @otherItem=ID FROM @Saved;DELETE @Saved;
INSERT CRM_Accounts(Name_AR,Brand_ID,AddedUser) VALUES(N'عميل عزل علامة أ',1,1);SET @a=SCOPE_IDENTITY();
INSERT CRM_Accounts(Name_AR,Brand_ID,AddedUser) VALUES(N'عميل عزل علامة ب',2,1);SET @b=SCOPE_IDENTITY();
INSERT Customer_Logins(AccountID,Username,PasswordHash,Salt,Iterations,ModifiedBy,SecurityStamp) VALUES(@a,'brand-isolation-test',CRYPT_GEN_RANDOM(32),CRYPT_GEN_RANDOM(32),210000,1,@stamp);
SET @xml=CONVERT(xml,CONCAT('<grants><grant id="',@catB,'" view="1" download="1"/></grants>'));
BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml;THROW 51999,'Customer granted foreign brand category',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @xml=CONVERT(xml,CONCAT('<grants><grant id="',@catA,'" view="1" download="0"/></grants>'));EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml;
EXEC Customer_WorkGuide_File @a,@stamp,@item,@catA,'view',0;
-- Even an invalid pre-existing database grant cannot widen the portal boundary.
INSERT CRM_WorkGuide_Access VALUES(@a,@catB,1,1);
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@otherItem,@catB,'view',0;THROW 51999,'Foreign brand view leaked through a stored grant',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
BEGIN TRY EXEC Customer_WorkGuide_List @a,@stamp,@catB;THROW 51999,'Foreign category list leaked',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
DELETE CRM_WorkGuide_Access WHERE Account_ID=@a AND Category_ID=@catB;
UPDATE CRM_Accounts SET Brand_ID=2 WHERE ID=@a;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@catA,'view',0;THROW 51999,'Account brand change retained old-brand access',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
SELECT @version=Row_Version FROM CRM_WorkGuide_AccessState WHERE Account_ID=@a;
BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml,@version;THROW 51999,'Stale previous-brand permission form saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
-- Moving a guide replaces its category links atomically; file pointer is retained.
SET @xml=N'<row><Brand_ID>2</Brand_ID><Name_AR>دليل منقول SQL</Name_AR><Name_EN>Moved guide</Name_EN><Summary_AR>ملخص</Summary_AR><Summary_EN>Summary</Summary_EN><Sort_Order>0</Sort_Order><Is_Active>1</Is_Active></row>';
SELECT @version=Row_Version FROM CRM_WorkGuide_Items WHERE ID=@item;
SET @links=CONVERT(xml,CONCAT('<categories><id>',@catB,'</id></categories>'));EXEC CRM_Save_WorkGuide_Item 1,@item,@xml,@links,@version;
IF NOT EXISTS(SELECT 1 FROM CRM_WorkGuide_Items WHERE ID=@item AND Brand_ID=2 AND File_Url LIKE '%22222222222222222222222222222222.pdf') OR EXISTS(SELECT 1 FROM CRM_WorkGuide_ItemCategories WHERE Item_ID=@item AND (Brand_ID<>2 OR Category_ID<>@catB)) THROW 51999,'Guide move corrupted links or file',1;
IF NOT EXISTS(SELECT 1 FROM CRM_Activity_Logs WHERE Entity='WorkGuide_Items' AND Record_ID=@item AND Before_Data.value('(/row/Brand_ID/text())[1]','int')=1 AND After_Data.value('(/row/Brand_ID/text())[1]','int')=2) THROW 51999,'Brand change audit missing',1;
DELETE CRM_WorkGuide_Access WHERE Account_ID IN(@a,@b);DELETE CRM_WorkGuide_AccessState WHERE Account_ID IN(@a,@b);
DELETE Customer_Portal_Activity WHERE AccountID IN(@a,@b);DELETE Customer_Logins WHERE AccountID IN(@a,@b);DELETE CRM_Activity_Logs WHERE Account_ID IN(@a,@b) OR (Entity='WorkGuide_Items' AND Record_ID IN(@item,@otherItem)) OR (Entity='WorkGuide_Categories' AND Record_ID IN(@catA,@catB));
DELETE CRM_WorkGuide_ItemCategories WHERE Item_ID IN(@item,@otherItem);DELETE CRM_WorkGuide_Items WHERE ID IN(@item,@otherItem);DELETE CRM_WorkGuide_Categories WHERE ID IN(@catA,@catB);DELETE CRM_Accounts WHERE ID IN(@a,@b);
DECLARE @reset nvarchar(200)=N'DBCC CHECKIDENT(''dbo.CRM_Accounts'',RESEED,'+CONVERT(nvarchar(40),@seed)+N') WITH NO_INFOMSGS;';EXEC(@reset);
SELECT 'PASS required brands, scoped duplicate names, parent/link integrity, grants/portal isolation, account-brand changes and audited atomic guide moves' Result;
